// 场景 A:用 tsc 编译、Node 运行
{ "compilerOptions": { "strict": true, "noUncheckedIndexedAccess": true, "module": "NodeNext" } }

// 场景 B:交给打包器(Vite/esbuild 等)
{ "compilerOptions": { "strict": true, "noUncheckedIndexedAccess": true, "module": "Preserve", "noEmit": true } }

examples.0.body.en:
// case A: tsc compiles, Node runs
{ "compilerOptions": { "strict": true, "noUncheckedIndexedAccess": true, "module": "NodeNext" } }

// case B: a bundler handles it (Vite/esbuild etc.)
{ "compilerOptions": { "strict": true, "noUncheckedIndexedAccess": true, "module": "Preserve", "noEmit": true } }
